/**
 * A PDF to try the desk with, for a visitor who has no file to hand: pdf.xyz's
 * own three pages — text on the first two, a form with two empty text fields
 * on the third — so the ticket has real facts to measure and say.
 *
 * The bytes ship with this module (`./sample-pdf-bytes`, generated by
 * `scripts/build-sample-pdf.ts`, which says why they are not built in the
 * tab), and this module is fetched only when "Try a sample PDF" is pressed.
 * The visitor's own files are never involved: the sample is staged like a
 * picked file, measured like one, and marked as the site's sample.
 */
import { SAMPLE_PDF_BASE64 } from "./sample-pdf-bytes";

/** The sample's file name — what the ticket's row shows. */
export const SAMPLE_PDF_NAME = "pdfxyz-sample.pdf";
export const SAMPLE_TITLE = "pdf.xyz sample";
export const SAMPLE_PAGES = 3;

/** The form fields the last page carries, by name and label. */
export const SAMPLE_FIELDS = [
  { name: "sample.name", label: "Name" },
  { name: "sample.date", label: "Date" },
] as const;

/** The sample's bytes, decoded. */
export function samplePdfBytes(): Uint8Array {
  return Uint8Array.from(atob(SAMPLE_PDF_BASE64), (c) => c.charCodeAt(0));
}

/** The sample, as a file the desk can take. */
export function samplePdfFile(): File {
  return new File([samplePdfBytes() as BlobPart], SAMPLE_PDF_NAME, {
    type: "application/pdf",
  });
}
